sealed interface Sekil permits Daire, Kare {}
record Daire(double r) implements Sekil {}
record Kare(double a) implements Sekil {}

double alan(Sekil s) {
    return switch (s) {
        case Daire d -> Math.PI * d.r() * d.r();
        case Kare k -> k.a() * k.a();
    };
}

